mapper.select:
SELECT dpc.id, dpc.param_id, dpc.param_name, dpc.param_value, dpc.param_unit, dpc.if_enable, su.user_name as updateName, dpc.update_time FROM data_param_config dpc left join sys_user su on dpc.update_by = su.id WHERE dpc.del_flag = 0 and dpc.data_type = 1 and dpc.if_hide = 0
and dpc.project_id = #{projectId}
and dpc.id = #{id}
and dpc.update_time >= #{startTime}
and dpc.update_time <= #{endTime}
and dpc.id in
#{item}
order by dpc.id

SELECT dpc.id, dpc.param_name, dpc.param_value, dpc.param_key, dpc.param_unit, su.user_name as updateName, dpc.update_time FROM data_param_config dpc left join sys_user su on dpc.update_by = su.id WHERE dpc.del_flag = 0 and dpc.data_type = 2
and dpc.project_id = #{projectId}
and dpc.chart_id = #{chartId}
and dpc.update_time >= #{startTime}
and dpc.update_time <= #{endTime}
order by dpc.id

select param_key as itemLable, param_value as itemValue from data_param_config where del_flag = 0 and data_type =2 and if_enable =1
and project_id = #{projectId}
and chart_id = #{chartId}
order by id
